from tests.host_lifespan_helpers import run_isolated_host


def test_full_host_uses_one_shared_bridge_connection_attempt_per_lifespan(tmp_path):
    run_isolated_host('from starlette.testclient import TestClient\nimport main\nimport main\n\n# Reach intentionally keeps an app singleton across TestClient entries.  Other\n# lifecycle tests may therefore have already exercised the same bridge object.\n# Measure connection attempts relative to the pre-entry count rather than\n# assuming a brand-new process/bridge with a literal zero counter.\nexisting_bridge = getattr(main, "voxel_bridge", None)\nattempts_before = getattr(existing_bridge, "_connection_attempts", 0)\n\nwith TestClient(main.app):\n    bridge = main.voxel_bridge\n    twin = main.app.state.twin_engine\n    pete = main.app.state.pete_enhanced\n    assert bridge is not None\n    assert twin.bridge is bridge\n    assert pete.bridge is bridge\n    assert pete._owns_bridge is False\n    first_attempts = bridge._connection_attempts\n    assert first_attempts == attempts_before + 1\n    assert bridge.is_connected is True\n\nassert bridge.is_connected is False\n\nwith TestClient(main.app):\n    assert main.voxel_bridge is bridge\n    assert main.app.state.twin_engine is twin\n    assert main.app.state.pete_enhanced is pete\n    assert bridge._connection_attempts == first_attempts + 1\n    assert bridge.is_connected is True\n    assert twin.health()["bridge_operational"] is True\n\nassert bridge.is_connected is False', tmp_path)
